import{_ as t,a0 as o,w as d,s as r,ao as l,I as p,a1 as e,A as i,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何在 Linux 中使用 LVM 创建和扩展交换分区 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 LVM 创建和扩展交换分区 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 LVM 创建和扩展交换分区 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 LVM 创建和扩展交换分区 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180328 How To Create-Extend Swap Partition In Linux Using LVM","title":"如何在 Linux 中使用 LVM 创建和扩展交换分区","tag":"201804","desc":""},"relativePath":"201804/20180328 How To Create-Extend Swap Partition In Linux Using LVM.md","filePath":"[post].md"}'),g={name:"201804/20180328 How To Create-Extend Swap Partition In Linux Using LVM.md"};function h(u,s,c,k,b,f){const n=o("Link");return d(),r("div",null,[s[15]||(s[15]=l('<h1 id="如何在-linux-中使用-lvm-创建和扩展交换分区" tabindex="-1">如何在 Linux 中使用 LVM 创建和扩展交换分区 <a class="header-anchor" href="#如何在-linux-中使用-lvm-创建和扩展交换分区" aria-label="Permalink to “如何在 Linux 中使用 LVM 创建和扩展交换分区”">​</a></h1><p>我们使用 LVM 进行灵活的卷管理，为什么我们不能将 LVM 用于交换分区呢？</p><p>这可以让用户在需要时增加交换分区。如果你升级系统中的内存，则需要添加更多交换空间。这有助于你管理运行需要大量内存的应用的系统。</p><p>可以通过三种方式创建交换分区</p><ul><li>创建一个新的交换分区</li><li>创建一个新的交换文件</li><li>在现有逻辑卷（LVM）上扩展交换分区</li></ul><p>建议创建专用交换分区而不是交换文件。</p><p><strong>建议阅读：</strong></p>',7)),p("ul",null,[p("li",null,[e(n,{href:"https://www.2daygeek.com/add-extend-increase-swap-space-memory-file-partition-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("3 种简单的方法在 Linux 中创建或扩展交换空间",-1)])]),_:1})]),p("li",null,[e(n,{href:"https://www.2daygeek.com/shell-script-create-add-extend-swap-space-linux/"},{default:i(()=>[...s[1]||(s[1]=[a("使用 Shell 脚本在 Linux 中自动创建/删除和挂载交换文件",-1)])]),_:1})])]),s[16]||(s[16]=l(`<p>Linux 中推荐的交换大小是多少？</p><h3 id="什么是交换空间" tabindex="-1">什么是交换空间 <a class="header-anchor" href="#什么是交换空间" aria-label="Permalink to “什么是交换空间”">​</a></h3><p>当物理内存 （RAM） 已满时，将使用 Linux 中的交换空间。当物理内存已满时，内存中的非活动页将移到交换空间。</p><p>这有助于系统连续运行应用程序，但它不能当做是更多内存的替代品。</p><p>交换空间位于硬盘上，因此它不能像物理内存那样处理请求。</p><h3 id="如何使用-lvm-创建交换分区" tabindex="-1">如何使用 LVM 创建交换分区 <a class="header-anchor" href="#如何使用-lvm-创建交换分区" aria-label="Permalink to “如何使用 LVM 创建交换分区”">​</a></h3><p>由于我们已经知道如何创建逻辑卷，所以交换分区也是如此。只需按照以下过程。</p><p>创建你需要的逻辑卷。在我这里，我要创建 <code>5GB</code> 的交换分区。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvcreate -L 5G -n LogVol_swap1 vg00</span></span>
<span class="line"><span> Logical volume &quot;LogVol_swap1&quot; created.</span></span></code></pre></div><p>格式化新的交换空间。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /dev/vg00/LogVol_swap1</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 5 GiB (5368705024 bytes)</span></span>
<span class="line"><span>no label, UUID=d278e9d6-4c37-4cb0-83e5-2745ca708582</span></span></code></pre></div><p>将以下条目添加到 <code>/etc/fstab</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/fstab</span></span>
<span class="line"><span>/dev/mapper/vg00-LogVol_swap1 swap swap defaults 0 0</span></span></code></pre></div><p>启用扩展逻辑卷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon -va</span></span>
<span class="line"><span>swapon: /swapfile: already active -- ignored</span></span>
<span class="line"><span>swapon: /dev/mapper/vg00-LogVol_swap1: found signature [pagesize=4096, signature=swap]</span></span>
<span class="line"><span>swapon: /dev/mapper/vg00-LogVol_swap1: pagesize=4096, swapsize=5368709120, devsize=5368709120</span></span>
<span class="line"><span>swapon /dev/mapper/vg00-LogVol_swap1</span></span></code></pre></div><p>测试交换空间是否已正确添加。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/swaps</span></span>
<span class="line"><span>Filename                Type        Size    Used    Priority</span></span>
<span class="line"><span>/swapfile file      1459804 526336  -1</span></span>
<span class="line"><span>/dev/dm-0 partition 5242876 0   -2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ free -g</span></span>
<span class="line"><span> total used free shared buff/cache available</span></span>
<span class="line"><span>Mem: 1 1 0 0 0 0</span></span>
<span class="line"><span>Swap: 6 0 6</span></span></code></pre></div><h3 id="如何使用-lvm-扩展交换分区" tabindex="-1">如何使用 LVM 扩展交换分区 <a class="header-anchor" href="#如何使用-lvm-扩展交换分区" aria-label="Permalink to “如何使用 LVM 扩展交换分区”">​</a></h3><p>只需按照以下过程来扩展 LVM 交换逻辑卷。</p><p>禁用相关逻辑卷的交换。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapoff -v /dev/vg00/LogVol_swap1</span></span>
<span class="line"><span>swapoff /dev/vg00/LogVol_swap1</span></span></code></pre></div><p>调整逻辑卷的大小。我将把交换空间从 <code>5GB</code> 增加到 <code>11GB</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvresize /dev/vg00/LogVol_swap1 -L +6G</span></span>
<span class="line"><span> Size of logical volume vg00/LogVol_swap1 changed from 5.00 GiB (1280 extents) to 11.00 GiB (2816 extents).</span></span>
<span class="line"><span> Logical volume vg00/LogVol_swap1 successfully resized.</span></span></code></pre></div><p>格式化新的交换空间。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /dev/vg00/LogVol_swap1</span></span>
<span class="line"><span>mkswap: /dev/vg00/LogVol_swap1: warning: wiping old swap signature.</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 11 GiB (11811155968 bytes)</span></span>
<span class="line"><span>no label, UUID=2e3b2ee0-ad0b-402c-bd12-5a9431b73623</span></span></code></pre></div><p>启用扩展逻辑卷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon -va</span></span>
<span class="line"><span>swapon: /swapfile: already active -- ignored</span></span>
<span class="line"><span>swapon: /dev/mapper/vg00-LogVol_swap1: found signature [pagesize=4096, signature=swap]</span></span>
<span class="line"><span>swapon: /dev/mapper/vg00-LogVol_swap1: pagesize=4096, swapsize=11811160064, devsize=11811160064</span></span>
<span class="line"><span>swapon /dev/mapper/vg00-LogVol_swap1</span></span></code></pre></div><p>测试逻辑卷是否已正确扩展。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -g</span></span>
<span class="line"><span> total used free shared buff/cache available</span></span>
<span class="line"><span>Mem: 1 1 0 0 0 0</span></span>
<span class="line"><span>Swap: 12 0 12</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat /proc/swaps</span></span>
<span class="line"><span>Filename                Type        Size    Used    Priority</span></span>
<span class="line"><span>/swapfile file      1459804 237024  -1</span></span>
<span class="line"><span>/dev/dm-0 partition 11534332    0   -2</span></span></code></pre></div><hr>`,30)),p("p",null,[s[3]||(s[3]=a("via: ",-1)),e(n,{href:"https://www.2daygeek.com/how-to-create-extend-swap-partition-in-linux-using-lvm/"},{default:i(()=>[...s[2]||(s[2]=[a("https://www.2daygeek.com/how-to-create-extend-swap-partition-in-linux-using-lvm/",-1)])]),_:1})]),p("p",null,[s[7]||(s[7]=a("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/ramya/"},{default:i(()=>[...s[4]||(s[4]=[a("Ramya Nuvvula",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[5]||(s[5]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[6]||(s[6]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const L=t(g,[["render",h]]);export{m as __pageData,L as default};
